#include<bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
const int K = 10;

int fa[MAXN];
vector<int> top[MAXN]; // top-K largest vertices in component

int gtf(int x) {
    while (fa[x] != x) {
        fa[x] = fa[fa[x]];
        x = fa[x];
    }
    return x;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);

    int n, q;
    cin >> n >> q;

    for (int i = 1; i <= n; i++) {
        fa[i] = i;
        top[i].push_back(i);
    }

    int op, x, y;
    for (int i = 0; i < q; i++) {
        cin >> op >> x >> y;
        if (op == 1) {
            int fx = gtf(x), fy = gtf(y);
            if (fx != fy) {
                // Merge top lists
                vector<int> merged;
                int a = 0, b = 0;
                while ((a < (int)top[fx].size() || b < (int)top[fy].size()) && (int)merged.size() < K) {
                    int va = (a < (int)top[fx].size()) ? top[fx][a] : -1;
                    int vb = (b < (int)top[fy].size()) ? top[fy][b] : -1;
                    if (va >= vb) {
                        merged.push_back(va);
                        a++;
                    } else {
                        merged.push_back(vb);
                        b++;
                    }
                }
                fa[fy] = fx;
                top[fx] = merged;
            }
        } else {
            int fx = gtf(x);
            int k = y;
            if (k <= (int)top[fx].size()) {
                cout << top[fx][k-1] << "\n";
            } else {
                cout << -1 << "\n";
            }
        }
    }

    return 0;
}

