		q.pop();
		if(vis[u])continue;
		vis[u]=true;
		for(auto [v,w]:g[u])
			if(dis[v]>dis[u]+w+a[v])
			{
				dis[v]=dis[u]+w+a[v];
				if(!vis[v])
					q.push({dis[v],v});
			}
	}
}
