#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int N;
ll X;
vector<ll> A, P, B, Q;

bool check(ll W) {
    ll total = 0;
    for (int i = 0; i < N; i++) {
        ll best = LLONG_MAX;
        // Try all combinations: j units of S, compute needed T
        // j ranges: we only need to check j from 0 to ceil(W/A[i])
        // but that can be huge. Use the trick: check around optimal
        ll max_s = (W + A[i] - 1) / A[i];
        // Check a window around the continuous optimum
        // x* = W * Q[i] / (A[i]*Q[i] + B[i]*P[i])
        // But to be safe, iterate key candidates
        for (ll j = max_s + 1; j >= max(0LL, max_s - 200); j--) {
            ll rem = W - A[i] * j;
            ll y = rem <= 0 ? 0 : (rem + B[i] - 1) / B[i];
            ll c = P[i] * j + Q[i] * y;
            best = min(best, c);
        }
        ll max_t = (W + B[i] - 1) / B[i];
        for (ll j = max_t + 1; j >= max(0LL, max_t - 200); j--) {
            ll rem = W - B[i] * j;
            ll x = rem <= 0 ? 0 : (rem + A[i] - 1) / A[i];
            ll c = Q[i] * j + P[i] * x;
            best = min(best, c);
        }
        total += best;
        if (total > X) return false;
    }
    return total <= X;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> X;
    A.resize(N); P.resize(N); B.resize(N); Q.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i] >> P[i] >> B[i] >> Q[i];
    }

    ll lo = 0, hi = 2e13;
    while (lo < hi) {
        ll mid = lo + (hi - lo + 1) / 2;
        if (check(mid)) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }

    cout << lo << "\n";
    return 0;
}

