#include<bits/stdc++.h>
using namespace std;
using ll=long long;

void solve()
{
    int n;
    ll M;
    cin >> n >> M;
    vector<ll> a(n+1);
    for(int i=1;i<=n;i++) cin>>a[i];

    // prefix[i] = a[1]+...+a[i], prefix[0]=0
    // distance from s to t = (prefix[t] - prefix[s-1] + total) % total
    // this is 0 mod M iff prefix[t] % M == prefix[s-1] % M
    // s in [1..N], t in [1..N], s != t
    // let i = s-1 in [0..N-1], j = t in [1..N]
    // need p[i] == p[j], with i != j (since s != t means i+1 != j, not i != j)
    // Wait: s != t. i = s-1, j = t. s != t means i+1 != j.
    // So we count pairs (i,j) with i in [0,N-1], j in [1,N], p[i]==p[j], i+1 != j.

    vector<ll> p(n+1);
    p[0] = 0;
    for(int i=1;i<=n;i++){
        p[i] = (p[i-1] + a[i] % M) % M;
    }

    // cnt0[r] = count of i in [0,N-1] with p[i]=r
    // cnt1[r] = count of j in [1,N] with p[j]=r
    map<ll,ll> cnt0, cnt1;
    for(int i=0;i<=n-1;i++) cnt0[p[i]]++;
    for(int j=1;j<=n;j++) cnt1[p[j]]++;

    ll ans = 0;
    for(auto &kv : cnt0){
        ll r = kv.first;
        if(cnt1.count(r)) ans += kv.second * cnt1[r];
    }

    // Subtract cases where i+1 == j (s == t)
    // i in [0,N-1], j = i+1 in [1,N], so j = i+1 always in [1,N]
    for(int i=0;i<=n-1;i++){
        int j = i+1; // j in [1,N]
        if(p[i] == p[j]) ans--;
    }

    cout << ans << "\n";
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    solve();
    return 0;
}

