void solve() {
    int n, m;
    cin >> n >> m;
    set<int> H, V, D1, D2;
    for(int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        H.insert(x);
        V.insert(y);
        D1.insert(x+y);
        D2.insert(x-y);
    }

    int freeR = n - (int)H.size();
    int freeC = n - (int)V.size();

    int ans = freeR * freeC;

    // For each blocked d1 diagonal, count squares in free rows and free cols on it
    for(auto d : D1) {
        // i+j = d, i in [1,n], j in [1,n], i not in H, j not in V
        // j = d - i, need 1 <= d-i <= n => d-n <= i <= d-1
        int lo = max(1LL, d - n);
        int hi = min(n, d - 1LL);
        if(lo > hi) continue;
        // count i in [lo,hi] not in H, with (d-i) not in V
        // total in range - those with i in H - those with (d-i) in V + those with i in H and (d-i) in V
        long long total = hi - lo + 1;
        long long inH = 0, inV = 0, inHV = 0;
        for(auto r : H) if(r >= lo && r <= hi) inH++;
        for(auto c : V) { int r = d - c; if(r >= lo && r <= hi) inV++; }
        for(auto r : H) { if(r >= lo && r <= hi) { int c = d - r; if(V.count(c)) inHV++; } }
        long long sub = total - inH - inV + inHV;
        ans -= sub;
    }

    // For each blocked d2 diagonal, count squares in free rows and free cols on it
    for(auto d : D2) {
        // i-j = d, j = i-d, need 1<=i<=n, 1<=i-d<=n => max(1,1+d)<=i<=min(n,n+d)
        int lo = max(1LL, 1LL + d);
        int hi = min(n, n + d);
        if(lo > hi) continue;
        long long total = hi - lo + 1;
        long long inH = 0, inV = 0, inHV = 0;
        for(auto r : H) if(r >= lo && r <= hi) inH++;
        for(auto c : V) { int r = d + c; if(r >= lo && r <= hi) inV++; }
        for(auto r : H) { if(r >= lo && r <= hi) { int c = r - d; if(c >= 1 && c <= n && V.count(c)) inHV++; } }
        long long sub = total - inH - inV + inHV;
