    int N;
    ll X;
    cin>>N>>X;
    vector<ll> A(N),Pv(N),B(N),Q(N);

    for(int i=0;i<N;i++){
        cin>>A[i]>> Pv[i]>> B[i] >> Q[i];
    }

    auto f=[&](ll x){
        ll res=X;
        for(int i=0;i<N;i++){
            ll val=INF;
            // enumerate s (machines of type A), need ceil((x - s*A[i])/B[i]) machines of type B
            ll max_s = (x + A[i] - 1) / A[i];
            for(ll s=max_s+1;s>=max(0LL,max_s-200);s--){
                ll rem = max(0LL, x - A[i]*s);
                ll t = (rem + B[i] - 1) / B[i];
                val=min(val, s*Pv[i] + t*Q[i]);
            }
            // also check s=0
            {
                ll s=0;
                ll rem = max(0LL, x - A[i]*s);
                ll t = (rem + B[i] - 1) / B[i];
                val=min(val, s*Pv[i] + t*Q[i]);
            }

            // enumerate t (machines of type B), need ceil((x - t*B[i])/A[i]) machines of type A
            ll max_t = (x + B[i] - 1) / B[i];
            for(ll t=max_t+1;t>=max(0LL,max_t-200);t--){
                ll rem = max(0LL, x - B[i]*t);
                ll s = (rem + A[i] - 1) / A[i];
                val=min(val, t*Q[i] + s*Pv[i]);
            }
            // also check t=0
            {
                ll t=0;
                ll rem = max(0LL, x - B[i]*t);
                ll s = (rem + A[i] - 1) / A[i];
                val=min(val, t*Q[i] + s*Pv[i]);
            }

            if(val==INF){
                return false;
            }
            res-=val;
        }
        return res>=0;
    };

